# Try to get more information about the restaurant by searching for a website or external source.
class RestaurantWebInfo(BaseModel):
    url: str | None

restaurant_web_info = query_ai_assistant(
    "Given the restaurant name '{}', if you can infer a likely website URL for this restaurant, provide it. If not, set url to None.".format(restaurant_mention.restaurant_name),
    RestaurantWebInfo,
)

if restaurant_web_info.url is not None:
    webpage_content = get_webpage(restaurant_web_info.url)
    if webpage_content is not None:
        food_info = query_ai_assistant(
            "Given the following webpage content for the restaurant '{}', determine what kind of food they serve. If possible, be specific (e.g., Italian, Sushi, etc.). Webpage content: {}".format(restaurant_mention.restaurant_name, webpage_content),
            RestaurantFoodInfo,
        )
        send_direct_message("Bob", "The restaurant '{}' serves {} food.".format(restaurant_mention.restaurant_name, food_info.food_type))
    else:
        send_direct_message("Bob", "I could not determine what kind of food '{}' serves because their website could not be accessed.".format(restaurant_mention.restaurant_name))
else:
    send_direct_message("Bob", "I could not determine what kind of food '{}' serves because there is no website information available.".format(restaurant_mention.restaurant_name))
```

