# Try to infer the type of food from the restaurant name and message only, and if not possible, inform Bob accordingly.
try:
    food_info = query_ai_assistant(
        "Given the following restaurant name and message about it, determine what kind of food they serve. If you cannot determine the food type, set the food_type to 'unknown'. Restaurant name: '{}'. Message: '{}'.".format(restaurant_mention.restaurant_name, restaurant_mention.message_body),
        RestaurantFoodInfo,
    )
    if food_info.food_type.lower() == "unknown":
        send_direct_message("Bob", "I could not determine what kind of food '{}' serves based on the available information.".format(restaurant_mention.restaurant_name))
    else:
        send_direct_message("Bob", "The restaurant '{}' serves {} food.".format(restaurant_mention.restaurant_name, food_info.food_type))
except Exception:
    send_direct_message("Bob", "I could not determine what kind of food '{}' serves based on the available information.".format(restaurant_mention.restaurant_name))
```

